/* M.A.T — «Combate táctico»: tu soldado (el de «Crea tu soldado») contra 1–6 soldados IA de Rusia o de EE. UU., visto desde arriba.
   Datos: soldado.json (pesos medidos y fichas de fabricante), fichas del Armero 3D (alcance, cadencia, calibre) y,
   para el equipo ruso que no está en soldado.json, cifras publicadas con su fuente. El combate es un modelo
   simplificado y transparente de M.A.T (un juego, no una predicción) con semilla para repetirlo. */
const EN=()=>window.MAT_LANG==='en'; const L=(es,en)=>EN()?en:es; const LL=a=>Array.isArray(a)?(EN()?(a[1]||a[0]):a[0]):(a||'');
const VER=(document.querySelector('script[data-v]')||{getAttribute(){return '1';}}).getAttribute('data-v');
const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const nf=(x,d)=>Number(x).toLocaleString(EN()?'en-GB':'es-ES',{minimumFractionDigits:d||0,maximumFractionDigits:d||0});
let DATA=null, ARM=null, ACTIVE=null;
function data(){ return DATA?Promise.resolve(DATA):fetch('soldado.json?v='+VER).then(r=>{ if(!r.ok) throw 0; return r.json(); }).then(d=>DATA=d); }
function arm(){ return ARM?Promise.resolve(ARM):import('./armero.js?v='+VER).then(m=>ARM=m); }
let REPLAY=null; function stopReplay(){ if(REPLAY){ try{ REPLAY.destroy(); }catch(e){} REPLAY=null; } }
function stop(){ stopReplay(); if(ACTIVE){ try{ ACTIVE.destroy(); }catch(e){} ACTIVE=null; } }
window.addEventListener('hashchange',()=>{ if(!/^#\/soldado\/combate/.test(location.hash)) stop(); });
