function aiSt(fac,mg){ const D=DATA, M=ARM; const c=FAC[fac].camo;
  if(fac==='us'){ const r=D.roles.find(x=>x.id===(mg?'ametrallador':'fusilero'))||D.roles.find(x=>x.id==='fusilero'); return {h:175,kg:80,role:r.id,lvl:0,q:Object.assign({},r.sel[0]),arma:JSON.parse(JSON.stringify(r.arma)),camo:'od',ucamo:c,gcamo:c,hcamo:c,gl:'tan',pc:'molle'}; }
  const wid=mg?['pkp','pkm'].find(id=>M.W.some(x=>x.id===id)):'ak12'; const w=M.W.find(x=>x.id===(wid||'ak12'))||M.W.find(x=>x.id==='ak12'); const v=w.V[0]; const ru=['pk120','1p87','1p63','kobra','obzor','p78','p29']; const opts=M.accs?M.accs(v,'optic'):[]; const opt=ru.find(a=>opts.includes(a));
  return {h:175,kg:80,role:null,lvl:0,q:{uni:1,boots:1,knee:1,gog:1,iba:1,ach:1},arma:{id:w.id,v:0,on:opt?{optic:opt}:{}},camo:'od',ucamo:c,gcamo:c,hcamo:c,gl:'negro',pc:'molle'}; }
