let C2=null;
export function route(app,ctx,p){ css(); stop(); ctx.set('<p class="sub" style="padding:30px 0">'+L('Cargando…','Loading…')+'</p>',L('Combate contra la IA','Fight the AI'));
  Promise.all([data(),arm(),C2?Promise.resolve(C2):import('./combate2d.js?v='+VER).then(m=>C2=m)]).then(()=>{ if(!/^#\/soldado\/combate/.test(location.hash)) return; page(app,ctx); }).catch(e=>{ console.warn(e); ctx.set(ctx.crumbs([[L('Inicio','Home'),'#/'],[L('Juegos','Games'),'#/juegos'],[L('Combate','Fight')]])+'<p class="sub">'+L('No se pudo cargar. Comprueba la conexión.','Could not load. Check your connection.')+'</p>'); }); }
/* ---- sonido: grabaciones reales de sonidos.json (cortadas en disparos sueltos) y explosión de dominio público; el AK-12, la PKM, el SCAR, el SR-25 y la M249 usan la grabación más cercana ---- */
const SND={m4:{f:'snd/arm_m4_carbine.mp3',sl:[[2.059, 0.091], [2.234, 0.32], [2.844, 0.276], [3.294, 0.131], [3.509, 0.166], [3.679, 0.32], [4.039, 0.32], [5.019, 0.171]]},m240:{f:'snd/arm_m240_machine_gun.mp3',sl:[[0.059, 0.161], [0.419, 0.176], [0.709, 0.201], [0.914, 0.296], [1.894, 0.241], [2.139, 0.32], [3.814, 0.32], [5.619, 0.32]]},mp7:{f:'snd/arm_heckler_koch_mp7.mp3',sl:[[0.229, 0.32], [0.569, 0.32], [2.089, 0.296], [2.389, 0.301], [2.764, 0.32], [3.719, 0.32], [5.464, 0.301], [6.749, 0.241]]},glock:{f:'snd/arm_glock.mp3',sl:[[0.234, 0.32], [0.794, 0.136], [0.934, 0.32], [2.734, 0.32], [3.714, 0.32], [4.959, 0.32], [6.544, 0.216], [6.829, 0.32]]},m2:{f:'snd/arm_m2_browning.mp3',sl:[[0.214, 0.086], [0.304, 0.111], [0.419, 0.106], [0.529, 0.111], [0.644, 0.231], [0.879, 0.116], [1.319, 0.141], [1.464, 0.32]]},boom:{f:'snd/explosion_ls100155.mp3',sl:[[0,1.6]]}};
const WSND={m4a1:'m4',scar:'m4',sr25:'m4',ak12:'m4',mp7:'mp7',mp7a1:'mp7',m82:'m2',m82a1:'m2',m249:'m240',m240:'m240',pkm:'m240',pkp:'m240',g18c:'glock',glock:'glock'};
const AU={ctx:null,buf:{},voices:0,last:{}}; let SND_ON=(()=>{ try{ return localStorage.getItem('mat_combate_snd')!=='0'; }catch(e){ return true; } })();
function auInit(){ if(AU.ctx) { if(AU.ctx.state==='suspended') AU.ctx.resume().catch(()=>{}); return; } try{ const AC=window.AudioContext||window.webkitAudioContext; if(AC) AU.ctx=new AC(); }catch(e){} }
function auLoad(k){ if(!AU.ctx||!SND[k]||AU.buf[k]!==undefined) return; AU.buf[k]=0; fetch(SND[k].f).then(r=>r.arrayBuffer()).then(b=>new Promise((ok,ko)=>AU.ctx.decodeAudioData(b,ok,ko))).then(d=>{ AU.buf[k]=d; }).catch(()=>{ AU.buf[k]=null; }); }
function auPlay(k,vol,pan){ if(!SND_ON||!AU.ctx||!AU.buf[k]||AU.voices>14||vol<0.02) return; const C=AU.ctx, sl=SND[k].sl[Math.floor(Math.random()*SND[k].sl.length)]; try{ const s=C.createBufferSource(); s.buffer=AU.buf[k]; const g=C.createGain(); const t=C.currentTime; g.gain.setValueAtTime(vol,t); g.gain.setValueAtTime(vol,t+Math.max(0.02,sl[1]-0.04)); g.gain.linearRampToValueAtTime(0,t+sl[1]); s.connect(g); let out=g; if(C.createStereoPanner){ const p=C.createStereoPanner(); p.pan.value=Math.max(-0.9,Math.min(0.9,pan||0)); g.connect(p); out=p; } out.connect(C.destination); AU.voices++; s.onended=()=>{ AU.voices--; }; s.start(t,sl[0],sl[1]+0.01); }catch(e){} }
const DIFN={rec:['Recluta','Recruit'],vet:['Veterano','Veteran'],eli:['Élite','Elite']}, DIFD={rec:['Tarda más en apuntar, falla más y casi no se mueve: para aprender.','Slower to aim, misses more and barely moves: for learning.'],vet:['El equilibrio de siempre.','The usual balance.'],eli:['Apunta rápido, acierta mucho más y cambia de cobertura sin parar.','Aims fast, hits far more often and keeps changing cover.']};
const MISN={despejar:['Despejar','Clear'],rehen:['Rescatar al rehén','Rescue the hostage'],trinchera:['Tomar la trinchera','Take the trench']}, MISD={despejar:['Gana si dejas fuera de combate a todos los enemigos.','Win by taking every enemy out of action.'],rehen:['Hay un rehén (punto blanco) en una habitación con un guardia al lado. Gana si tu soldado llega hasta él; si el rehén muere (por una granada o por el apoyo), pierdes. Tu soldado no lanza granadas cerca del rehén, y el apoyo apunta lejos de él (aunque la dispersión puede alcanzarlo).','There is a hostage (white dot) in a room with a guard next to it. Win if your soldier reaches it; if the hostage dies (grenade or strike), you lose. Your soldier throws no grenades near the hostage, and any strike aims away from it (dispersion can still reach it).'],trinchera:['Solo en Trincheras: gana si mantienes el tramo central 6 segundos sin enemigos dentro (o si los abates a todos). Dos defensores empiezan dentro.','Trenches only: win by holding the central bay for 6 seconds with no enemy inside (or by taking them all down). Two defenders start inside.']};
function loadCfg(){ let c=null; try{ c=JSON.parse(localStorage.getItem('mat_combate_cfg')||'null'); }catch(e){} c=Object.assign({fac:'ru',n:3,map:'casa',night:false,air:'none',dif:'vet',mi:'despejar',eq:1},c||{}); if(![1,2,4].includes(+c.eq)) c.eq=1; c.eq=+c.eq; if(!FAC[c.fac]) c.fac='ru'; if(!MAPN[c.map]) c.map='casa'; if(!STRIKES[c.air]) c.air='none'; if(!DIFN[c.dif]) c.dif='vet'; if(!MISN[c.mi]) c.mi='despejar'; if(c.mi==='trinchera') c.map='trincheras'; c.n=Math.max(1,Math.min(6,c.n|0||1)); return c; }
function saveCfg(c){ try{ localStorage.setItem('mat_combate_cfg',JSON.stringify(c)); }catch(e){} }
const RM=()=>{ try{ return matchMedia('(prefers-reduced-motion: reduce)').matches; }catch(e){ return false; } };
function page(app,ctx){ const D=DATA, M=ARM; const cfg=loadCfg(); const sv=new URLSearchParams(location.hash.split('?')[1]||'');
  if(sv.get('f')&&FAC[sv.get('f')]) cfg.fac=sv.get('f'); if(sv.get('m')&&MAPN[sv.get('m')]) cfg.map=sv.get('m'); if(sv.get('n')) cfg.n=Math.max(1,Math.min(6,parseInt(sv.get('n'),10)||1)); if(sv.get('t')) cfg.night=sv.get('t')==='noche'; if(sv.get('a')&&STRIKES[sv.get('a')]) cfg.air=sv.get('a'); if(sv.get('d')&&DIFN[sv.get('d')]) cfg.dif=sv.get('d'); if(sv.get('e')&&[1,2,4].includes(+sv.get('e'))) cfg.eq=+sv.get('e'); else if(sv.get('s')) cfg.eq=1; if(sv.get('mi')&&MISN[sv.get('mi')]){ cfg.mi=sv.get('mi'); if(cfg.mi==='trinchera') cfg.map='trincheras'; }
  let seed=parseInt(sv.get('s'),10); let shared=seed>0; if(!(seed>0)) seed=1+Math.floor(Math.random()*99999);
  const mine=loadSt(); if(!mine.arma&&mine.role){ const r=D.roles.find(x=>x.id===mine.role); if(r) mine.arma=r.arma; }
  const ok=!!(mine.arma&&wInfo(mine.arma));
  const head=ctx.crumbs([[L('Inicio','Home'),'#/'],[L('Juegos','Games'),'#/juegos'],[L('Combate','Fight')]])+
    '<h1>'+L('Combate táctico contra la IA','Tactical fight vs the AI')+'</h1><p class="sub">'+L('Tu soldado de «Crea tu soldado» (punto azul) contra 1–6 soldados con el equipo real de Rusia o de EE. UU. (puntos rojos), visto desde arriba. Solo ves a los enemigos que entran en tu cono de visión.','Your soldier from “Build your soldier” (blue dot) against 1–6 soldiers with the real kit of Russia or the USA (red dots), seen from above. You only see enemies inside your vision cone.')+'</p>';
  if(!ok){ ctx.set(head+'<div class="cb-card"><h2>'+L('Primero crea tu soldado','Build your soldier first')+'</h2><p>'+L('Elige un rol o tu equipo y un arma en «Crea tu soldado». El combate usa exactamente ese soldado.','Choose a role or your gear and a weapon in “Build your soldier”. The fight uses exactly that soldier.')+'</p><a class="cb-btn grn" href="#/soldado">'+L('Ir a Crea tu soldado','Go to Build your soldier')+'</a></div>',L('Combate contra la IA','Fight the AI')); return; }
  const E='<span class="cb-est">'+L('Estimación','Estimate')+'</span>';
  const enemyPs=()=>{ const out=[]; for(let i=0;i<cfg.n;i++){ const mg=cfg.n>=4&&i===cfg.n-1; out.push(profile(cfg.fac,aiSt(cfg.fac,mg),cfg.fac)); } return out; };
  function render(){ const PA=profile('me',mine,null), RS=enemyPs(), PB=RS[0]; const KA=kit2d(PA), KB=kit2d(PB); const mgP=RS.length>=4?RS[RS.length-1]:null;
    const nightTxt=(K,P)=>P.kind==='ru'?L('Miras nocturna/térmica 1PN140 y 1PN141 (Ratnik); sin gafas de visión nocturna','1PN140 and 1PN141 night/thermal weapon sights (Ratnik); no night-vision goggles'):[K.nvg?(K.nvgN||L('Visor nocturno','Night vision')):L('Sin visión nocturna','No night vision'),K.light?L('linterna en el arma','weapon light'):null,K.laserN?(K.laserN+(K.irLaser?L(' (láser IR)',' (IR laser)'):'')):null].filter(Boolean).join(' · ');
    const side=(P,K,t,extra)=>{ const wi=P.wi; return '<div class="cb-side"><h3>'+t+'</h3><ul><li><b>'+L('Arma','Weapon')+':</b> '+esc(wi?wi.name:'—')+(wi&&wi.optN?' + '+esc(wi.optN):(wi?L(' (miras de hierro)',' (iron sights)'):''))+'</li><li><b>'+L('Chaleco','Vest')+':</b> '+esc(P.vestN)+(P.vestCls?' <small>('+esc(P.vestCls)+')</small>':'')+'</li><li><b>'+L('Casco','Helmet')+':</b> '+esc(P.helmN)+'</li><li><b>'+L('Noche','Night')+':</b> '+esc(nightTxt(K,P))+'</li><li><b>'+L('Granadas','Grenades')+':</b> '+(K.frags?K.frags+' × M67':P.kind==='ru'?L('sin dato en el equipo Ratnik: 0','no figure in the Ratnik kit: 0'):'0')+'</li>'+(extra||'')+'</ul></div>'; };
    const rowBar=(v,max,cls)=>'<div class="cb-bar '+(cls||'')+'"><i style="width:'+Math.max(3,Math.min(100,v/max*100)).toFixed(0)+'%"></i></div>';
    const wa=PA.wi, wb=PB.wi; const nv=K=>K.nvg?40:K.nightSight?40:K.light?25:8;
    const tbl='<table class="cb-tbl"><tr><th></th><th>'+L('Tú','You')+'</th><th>'+FAC[cfg.fac].flag+' '+L('IA','AI')+'</th></tr>'+
      '<tr><th>'+L('Protección','Protection')+'</th><td>'+(PA.plate?L('Placas de fusil ×','Rifle plates ×')+PA.plateN:L('Sin placas de fusil','No rifle plates'))+(PA.helmet?L(' · casco',' · helmet'):'')+rowBar(PA.prot,85)+'</td><td>'+(PB.plate?L('Placas de fusil ×','Rifle plates ×')+PB.plateN:'—')+(PB.helmet?L(' · casco',' · helmet'):'')+rowBar(PB.prot,85,'b')+'</td></tr>'+
      '<tr><th>'+L('Potencia de fuego','Firepower')+'</th><td>'+esc(wa.cal)+'<br>'+(wa.cad?esc(wa.cad):'—')+rowBar(PA.fire,100)+'</td><td>'+esc(wb.cal)+'<br>'+(wb.cad?esc(wb.cad):'—')+(mgP?'<br><small>+ '+esc(mgP.wi.name)+'</small>':'')+rowBar(PB.fire,100,'b')+'</td></tr>'+
      '<tr><th>'+L('Alcance eficaz','Effective range')+'</th><td>'+(wa.alc?nf(wa.alc)+' m':'—')+rowBar(wa.alc||0,1100)+'</td><td>'+(wb.alc?nf(wb.alc)+' m':'—')+rowBar(wb.alc||0,1100,'b')+'</td></tr>'+
      '<tr><th>'+L('Óptica','Optic')+'</th><td>'+(wa.optN?esc(wa.optN)+(wa.mag>1?' ('+nf(wa.mag,wa.mag%1?1:0)+'×)':' (1×)'):L('Miras de hierro','Iron sights'))+'</td><td>'+(wb.optN?esc(wb.optN)+(wb.mag>1?' ('+nf(wb.mag,wb.mag%1?1:0)+'×)':' (1×)'):L('Miras de hierro','Iron sights'))+'</td></tr>'+
      '<tr><th>'+L('Visión de noche','Night vision')+'</th><td>'+nf(nv(KA))+' m'+E+rowBar(nv(KA),40)+'</td><td>'+nf(nv(KB))+' m'+(KB.nightSight?L(' (solo por el visor)',' (through the sight only)'):'')+E+rowBar(nv(KB),40,'b')+'</td></tr>'+
      '<tr><th>'+L('Movilidad','Mobility')+'</th><td>'+nf(PA.pct)+' % '+L('del peso corporal','of body weight')+' · «'+esc(LL(PA.band.n))+'»'+rowBar(100-Math.min(100,PA.pct),100)+'</td><td>'+nf(PB.pct)+' % · «'+esc(LL(PB.band.n))+'»'+(PB.est.kg?E:'')+rowBar(100-Math.min(100,PB.pct),100,'b')+'</td></tr>'+
      '<tr><th>'+L('Peso total','Total weight')+'</th><td>'+nf(PA.tot,1)+' kg</td><td>'+(PB.est.kg?'≥ ':'')+nf(PB.tot,1)+' kg'+(PB.kgNote?' <small>('+esc(PB.kgNote)+')</small>'+E:'')+'</td></tr></table>';
    const srcs='<div class="cb-src">'+L('Fuentes: arma, calibre, cadencia y alcance de la ficha del Armero 3D; pesos de tu equipo y del soldado de EE. UU. de soldado.json (Ejército de EE. UU. y fichas de fabricante); bandas de movilidad de ATP 3-21.18 (2017); granada M67 (radio mortal 5 m, de heridas 15 m, retardo 4–5 s): ','Sources: weapon, calibre, rate of fire and range from the 3D Gunsmith data sheet; weights of your kit and the US soldier from soldado.json (US Army and maker data sheets); mobility bands from ATP 3-21.18 (2017); M67 grenade (5 m fatality and 15 m injury radius, 4–5 s delay): ')+'<a href="https://en.wikipedia.org/wiki/M67_grenade" target="_blank" rel="noopener">Wikipedia (en) — «M67 grenade»</a>. '+
      (cfg.fac==='ru'?L('Equipo ruso: ','Russian kit: ')+'<a href="'+SRC.ratnik_en[1]+'" target="_blank" rel="noopener">'+SRC.ratnik_en[0]+'</a> (6B45: 7,5 kg, '+L('clase 6; miras 1PN140/1PN141','class 6; 1PN140/1PN141 sights')+'); <a href="'+SRC.ratnik_ru[1]+'" target="_blank" rel="noopener">'+SRC.ratnik_ru[0]+'</a> (6B47: 1,056 kg). '+L('El AK-12 no lleva miras rusas de día porque no están modeladas en el Armero.','The AK-12 has no Russian day optic because none is modelled in the Gunsmith.')+' ':'')+
      L('Las barras y las distancias de visión nocturna son una escala de M.A.T (estimación); los números de arma, peso y blindaje son los publicados.','The bars and night-vision distances are an M.A.T scale (estimate); weapon, weight and armour figures are the published ones.')+'</div>';
    const chips=(id,list,cur)=>'<div class="cb-chips" id="'+id+'">'+list.map(([v,t])=>'<button type="button" class="cb-chip'+(String(v)===String(cur)?' on':'')+'" data-v="'+v+'" aria-pressed="'+(String(v)===String(cur))+'">'+t+'</button>').join('')+'</div>';
    const S_=STRIKES[cfg.air];
    const airBox=cfg.air==='none'?'<p class="cb-note">'+L('Entras sin apoyo: la puntuación de realismo no baja.','You go in without support: the realism score stays whole.')+'</p>':'<div class="cb-air"><p><b>'+esc(LL(S_.n))+'</b></p><p>'+esc(LL(S_.facts))+' — <a href="'+S_.src[1]+'" target="_blank" rel="noopener">'+esc(S_.src[0])+'</a></p><p>'+E+' '+esc(LL(S_.est))+L('; y la puntuación','; and the score')+'.</p><p class="cb-note">'+L('El punto de mira cambia en cada partida: la posición de un enemigo o un edificio al azar, y el impacto cae alrededor con la dispersión del arma (se marca en el mapa). ','The aim point changes every game: an enemy position or a random building, and the impact lands around it with the weapon’s dispersion (marked on the map). ')+L('Un solo apoyo por misión, antes de entrar: tu soldado espera a cubierto fuera del mapa. Coste: −'+S_.cost+' puntos de realismo (usar esto contra '+cfg.n+' soldado'+(cfg.n>1?'s':'')+' es desproporcionado).','One strike per mission, before going in: your soldier waits in cover off the map. Cost: −'+S_.cost+' realism points (using this against '+cfg.n+' soldier'+(cfg.n>1?'s':'')+' is disproportionate).')+'</p></div>';
    ctx.set(head+'<div class="cb-card"><h2>'+L('1 · Misión','1 · Mission')+'</h2>'+
      '<h3 class="cb-h3">'+L('Bando enemigo','Enemy side')+'</h3>'+chips('cbfac',['ru','us'].map(f=>[f,FAC[f].flag+' '+LL(FAC[f].n)]),cfg.fac)+
      '<h3 class="cb-h3">'+L('Número de enemigos','Number of enemies')+'</h3>'+chips('cbn',[1,2,3,4,5,6].map(n=>[n,String(n)]),cfg.n)+(cfg.n>=4?'<p class="cb-note">'+L('Con 4 o más, uno lleva ametralladora.','With 4 or more, one carries a machine gun.')+'</p>':'')+
      '<h3 class="cb-h3">'+L('Tu equipo','Your team')+'</h3>'+chips('cbeq',[[1,L('Solo (1)','Solo (1)')],[2,L('Binomio (2)','Pair (2)')],[4,L('Grupo (4)','Team (4)')]],cfg.eq)+'<p class="cb-note">'+(cfg.eq===1?L('Vas solo: '+cfg.eq+' contra '+cfg.n+'.','You go alone: '+cfg.eq+' vs '+cfg.n+'.'):L(cfg.eq+' contra '+cfg.n+': '+(cfg.eq-1)+(cfg.eq>2?' compañeros (azul claro) llevan':' compañero (azul claro) lleva')+' tu mismo equipo, te cubren la espalda y los ángulos y entran contigo. No hay fuego amigo. Si caes tú, se pierde la misión.',cfg.eq+' vs '+cfg.n+': '+(cfg.eq-1)+' teammate'+(cfg.eq>2?'s':'')+' (light blue) carry your kit, cover your back and angles and go in with you. No friendly fire. If you fall, the mission is lost.'))+'</p>'+
      '<h3 class="cb-h3">'+L('Dificultad de la IA','AI difficulty')+'</h3>'+chips('cbdif',Object.keys(DIFN).map(k=>[k,LL(DIFN[k])]),cfg.dif)+'<p class="cb-note">'+esc(LL(DIFD[cfg.dif]))+'</p>'+
      '<h3 class="cb-h3">'+L('Mapa','Map')+'</h3>'+chips('cbmap',Object.keys(MAPN).map(k=>[k,LL(MAPN[k])]),cfg.map)+'<p class="cb-note">'+esc(LL(MAPD[cfg.map]))+'</p>'+
      '<h3 class="cb-h3">'+L('Misión','Mission')+'</h3>'+chips('cbmi',Object.keys(MISN).map(k=>[k,k==='despejar'&&cfg.map==='casa'?L('Despejar la casa','Clear the house'):LL(MISN[k])]),cfg.mi)+'<p class="cb-note">'+esc(LL(MISD[cfg.mi]))+'</p>'+
      '<h3 class="cb-h3">'+L('Hora','Time')+'</h3>'+chips('cbt',[['dia',L('☀️ Día','☀️ Day')],['noche',L('🌙 Noche','🌙 Night')]],cfg.night?'noche':'dia')+'<p class="cb-note">'+L('De noche los conos de visión se acortan a unos 8 m. El visor nocturno o la mira nocturna los devuelven a unos 40 m; la linterna alumbra 25 m pero te delata; el láser IR solo ayuda si llevas visor nocturno.','At night vision cones shrink to about 8 m. Night-vision goggles or a night sight bring them back to about 40 m; a weapon light reaches 25 m but gives you away; the IR laser only helps with night vision.')+E+'</p>'+
      '<h3 class="cb-h3">'+L('Apoyo antes de entrar (opcional)','Support before going in (optional)')+'</h3>'+chips('cbair',Object.keys(STRIKES).map(k=>[k,(STRIKES[k].icon?STRIKES[k].icon+' ':'')+LL(STRIKES[k].n).replace(/ \(.*\)$/,'')]),cfg.air)+airBox+'</div>'+
      '<div class="cb-card"><h2>'+L('2 · Los equipos','2 · The kits')+'</h2><div class="cb-two">'+side(PA,KA,'🔵 '+L('Tu soldado','Your soldier'))+side(PB,KB,'🔴 '+FAC[cfg.fac].flag+' '+L('Soldado IA','AI soldier')+' × '+cfg.n,mgP?'<li><b>'+L('Ametrallador','Machine gunner')+':</b> '+esc(mgP.wi.name)+'</li>':'')+'</div>'+tbl+srcs+'</div>'+
      '<div class="cb-card" id="cbgo"><h2>'+L('3 · Combate','3 · Fight')+'</h2><p class="cb-note">'+L('Tu soldado (y tu equipo, si llevas) limpia habitación por habitación como en CQB: avanza pegado al muro, se para en cada puerta, se asoma por partes («cortar el pastel») mientras otro cubre, entra, revisa las esquinas y da la habitación por despejada antes de seguir. La IA enemiga hace lo mismo: un equipo (punta, cobertura y retaguardia que mira atrás) limpia habitaciones hacia donde te vio u oyó, avisa por radio con un pequeño retraso, hace fuego de supresión y a veces flanquea por otra puerta; otros se quedan fijos vigilando una puerta o un pasillo. Nadie se queda quieto: ráfagas cortas y salto a la siguiente cobertura, asomarse por esquinas y marcos de puerta, agacharse y arrastrarse bajo fuego, recargar a cubierto. Cada enemigo tiene su carácter (agresivo, prudente o flanqueador) y reacciona a dónde te ve u oye. En cada partida nueva salen en sitios distintos. El resultado sale de un modelo sencillo y transparente con los datos de arriba, la cobertura, la noche y algo de azar','Your soldier (and your team, if you bring one) clears room by room CQB-style: moves along the wall, stops at each door, slices the pie while another covers, goes in, checks the corners and calls the room clear before moving on. The enemy AI does the same: a team (point, cover and a rear man watching behind) clears rooms towards where it saw or heard you, radios with a short delay, lays down suppressive fire and sometimes flanks through another door; others stay put holding a door or a corridor. Nobody stands still: short bursts and a bound to the next cover, peeking round corners and door frames, ducking and crawling under fire, reloading in cover. Each enemy has a character (aggressive, cautious or flanker) and reacts to where it sees or hears you. Every new game they start in different places. The outcome comes from a simple, transparent model using the data above, cover, night and some chance')+(shared?L(' (partida compartida, semilla ',' (shared game, seed ')+seed+')':'')+L('. Es un juego, no una predicción.','. It is a game, not a prediction.')+'</p><button type="button" class="cb-btn" id="cbstart">'+L('▶ Empezar misión','▶ Start mission')+'</button> <a class="cb-btn sec" href="#/soldado">'+L('Cambiar mi equipo','Change my kit')+'</a>'+
      '<details class="cb-src" style="margin-top:10px"><summary>'+L('Cómo se calcula','How it is calculated')+'</summary><p>'+L('Cada bala: probabilidad base según la distancia (0,62·e^(−d/28)+0,04), ×1,3 con óptica de 3× o más a más de 25 m, ×1,1 con punto rojo, ×0,45 si el blanco está tras cobertura baja, una ventana o asomado por una esquina o un marco de puerta, ×0,15 si está agachado por la supresión, ×0,8 si se mueve (×0,55 si se arrastra), ×(1−0,5·supresión del tirador); de noche ×0,8 sin ayudas, ×0,85 con visor nocturno sin láser IR y ×1 con los dos. Impacto: 10 % cabeza (baja), 50 % torso (la placa lo para el 70 % de las veces con dos placas, 55 % con una), 40 % extremidades. Supresión: cada bala cercana la sube; por encima de 0,75 el soldado se agacha. Velocidad: 2,4 m/s dividida por el factor de carga de ATP 3-21.18 (arrastrándose, el 38 %). Tras unas ráfagas cada soldado salta a otra cobertura desde la que vea al enemigo; sin balas, se pone a cubierto para recargar. Recarga 2,6 s (fusil) y 7 s (ametralladora). Todo esto son estimaciones de M.A.T.','Each round: base chance from distance (0.62·e^(−d/28)+0.04), ×1.3 with a 3× or higher optic beyond 25 m, ×1.1 with a red dot, ×0.45 if the target is behind low cover, a window or peeking round a corner or door frame, ×0.15 if pinned down, ×0.8 if moving (×0.55 if crawling), ×(1−0.5·shooter suppression); at night ×0.8 with no aids, ×0.85 with night vision but no IR laser, ×1 with both. Hit: 10 % head (down), 50 % torso (plate stops it 70 % of the time with two plates, 55 % with one), 40 % limbs. Suppression: every near miss raises it; above 0.75 the soldier ducks. Speed: 2.4 m/s divided by the ATP 3-21.18 load factor (38 % when crawling). After a few bursts each soldier bounds to another cover with a view of the enemy; out of ammunition, it gets into cover to reload. Reload 2.6 s (rifle) and 7 s (machine gun). All of these are M.A.T estimates.')+'</p></details></div><div id="cbfight"></div>',L('Combate contra la IA','Fight the AI'));
    const bind=(id,fn)=>{ const el=document.getElementById(id); if(el) el.addEventListener('click',e=>{ const b=e.target.closest('button[data-v]'); if(!b) return; fn(b.getAttribute('data-v')); saveCfg(cfg); const y=window.scrollY; render(); window.scrollTo(0,y); }); };
    bind('cbfac',v=>cfg.fac=v); bind('cbn',v=>cfg.n=+v); bind('cbmap',v=>{ cfg.map=v; if(v!=='trincheras'&&cfg.mi==='trinchera') cfg.mi='despejar'; }); bind('cbdif',v=>cfg.dif=v); bind('cbeq',v=>cfg.eq=+v); bind('cbmi',v=>{ cfg.mi=v; if(v==='trinchera') cfg.map='trincheras'; }); bind('cbt',v=>cfg.night=v==='noche'); bind('cbair',v=>cfg.air=v);
    document.getElementById('cbstart').addEventListener('click',()=>{ saveCfg(cfg); const sd=shared?seed:1+Math.floor(Math.random()*99999); shared=false; fight(PA,RS,sd); }); }
  /* ---------------- la partida ---------------- */
  function fight(PA,RS,sd){ stop(); seed=sd; const box=document.getElementById('cbfight'); const KA=kit2d(PA), KR=RS.map(kit2d); const rm=RM();
    box.innerHTML='<div class="cb-card cb-play"><div class="cb-top"><div class="cb-hp"><b>🔵 '+L('Tu soldado','Your soldier')+' · '+esc(KA.short)+'</b><div class="g"><i id="cbhpA"></i></div><small id="cbammo"></small></div><div class="cb-hp r"><b>🔴 '+L('Enemigos','Enemies')+': <span id="cbleft">'+RS.length+'/'+RS.length+'</span></b><div class="cb-dots" id="cbdots"></div><small id="cbtime">0:00</small></div></div>'+
      '<div class="cb-stage2" id="cbstage"><canvas id="cbcv"></canvas><div class="cb-ban" id="cbban" hidden></div><div class="cb-slowmo" id="cbslowmo" hidden>🎞 '+L('Cámara lenta','Slow motion')+'</div><div class="cb-tools"><button type="button" id="cbsnd" aria-label="'+L('Sonido','Sound')+'">'+(SND_ON?'🔊':'🔇')+'</button><button type="button" id="cbsp">×1</button><button type="button" id="cbskip">'+L('⏭ Saltar','⏭ Skip')+'</button></div></div>'+
      '<p class="cb-note" id="cbslow" hidden>'+L('Tu móvil va justo: he bajado la resolución del mapa para que vaya fluido.','Your phone is struggling: map resolution lowered to keep it smooth.')+'</p><h3 class="cb-h3">'+L('Registro','Log')+'</h3><ul class="cb-log" id="cblog"></ul></div><div id="cbres"></div>';
    const stg=document.getElementById('cbstage'), cv=document.getElementById('cbcv'); const simO={seed,night:cfg.night,dif:cfg.dif,mission:cfg.mi,team:cfg.eq}; const sim=C2.makeSim(cfg.map,KA,KR,simO); const Mp=sim.M;
    auInit(); const sk=K=>WSND[K.wid]||(K.mg?'m240':'m4'); [sk(KA)].concat(KR.map(sk),['boom']).forEach(auLoad); let speedRef=1;
    const auPos=(x,y)=>{ const B=sim.B; const d=Math.hypot(x-B.x,y-B.y); const r=cv.getBoundingClientRect(); let pan=0; try{ const p=view.tx(x,y); pan=(p[0]/Math.max(1,r.width)-0.5)*1.4; }catch(e){} return [d,pan]; };
    sim.onShot=(a)=>{ const k=a.kit; const key=sk(k); const now=performance.now(); const gap=speedRef>=4?90:speedRef>=2?45:0; if(gap&&now-(AU.last[a.id]||0)<gap) return; AU.last[a.id]=now; const [d,pan]=auPos(a.x,a.y); auPlay(key,(a.team===0?0.42:0.5)*Math.min(1,5/(d+3))*(key==='mp7'?1.4:1),pan); };
    sim.onBoom=(x,y,big)=>{ const [d,pan]=auPos(x,y); auPlay('boom',Math.min(0.9,(0.35+0.3*(big||1))*Math.min(1,10/(d+6))),pan); };
    function size(){ const w=stg.clientWidth; const port=w<600; const asp=port?Mp.w/Mp.h:Mp.h/Mp.w; let h=Math.round((w-16)*asp+16); h=Math.min(h,Math.round(window.innerHeight*(port?0.78:0.74))); stg.style.height=Math.max(260,h)+'px'; }
    size(); const vo={dprK:1,redTracer:cfg.fac==='ru'?'#7dff6a':'#ff7a5c'}; const view=C2.makeView(cv,sim,vo);
    try{ box.firstChild.scrollIntoView({behavior:rm?'auto':'smooth',block:'start'}); }catch(e){}
    let speed=1, acc=0, last=performance.now(), raf=0, dead=false, shown=0, resT=0; const fts=[]; let slowed=0;
    /* apoyo de fuego */
    const st=cfg.air!=='none'?Object.assign({},STRIKES[cfg.air]):null; let animEnd=0, impactAt=0, applied=false; const t0=performance.now();
    if(st){ const R2=C2.rng(seed+7); const reds=sim.reds; const rooms=(Mp.rooms||[]).filter(r=>!/calle|street/.test(r[4][1]));
      /* punto de mira: la posición de un enemigo al azar (70 %) o un edificio/habitación al azar (30 %); impacto con la dispersión del arma (error circular probable) */
      const Hs=sim.hostage, safe=(x,y)=>!Hs||Math.hypot(x-Hs.x,y-Hs.y)>st.rD*2+st.cep*1.5; const redsS=reds.filter(e=>safe(e.x,e.y)), roomsS=rooms.filter(r=>safe(r[0]+r[2]/2,r[1]+r[3]/2)); const reds_=redsS.length?redsS:reds, rooms_=Hs?roomsS:rooms; /* con rehén: no se apunta cerca de él */
      let aim, aimN; if(R2()<0.7||!rooms_.length){ const e=reds_[Math.floor(R2()*reds_.length)]; aim=[e.x,e.y]; aimN=[L('la posición del '+e.name.toLowerCase(),e.name+'’s position'),'']; } else { const r=rooms_[Math.floor(R2()*rooms_.length)]; aim=[r[0]+r[2]/2,r[1]+r[3]/2]; aimN=[LL(r[4]),'']; }
      const gs=()=>{ const u=Math.max(1e-9,R2()), v=R2(), m=Math.sqrt(-2*Math.log(u)); return [m*Math.cos(6.2832*v),m*Math.sin(6.2832*v)]; }; const sig=st.cep/1.1774; const cl=([x,y])=>[Math.max(0.5,Math.min(Mp.w-0.5,x)),Math.max(0.5,Math.min(Mp.h-0.5,y))];
      st.aim=aim; st.aimN=aimN[0]; const g0=gs(); st.at=cl([aim[0]+g0[0]*sig,aim[1]+g0[1]*sig]);
      if(st.rounds){ st.rounds=[]; for(let i=0;i<6;i++){ const g=gs(); st.rounds.push(cl([aim[0]+g[0]*sig,aim[1]+g[1]*sig])); } st.at=st.rounds[0]; }
      st.miss=Math.hypot(st.at[0]-aim[0],st.at[1]-aim[1]);
      const k=rm?0.35:1; impactAt=(cfg.air==='mortar'?0.8+5*0.42+0.1:2.4)*k; animEnd=impactAt+(rm?0.6:1.6);
      const booms=(st.rounds||[st.at]).map((p,i)=>({x:p[0],y:p[1],t:cfg.air==='mortar'?(0.8+i*0.42)*k:impactAt}));
      const puffs=[]; const PR=C2.rng(seed+11); booms.forEach(b=>{ const n=cfg.air==='mortar'?5:14; for(let i=0;i<n;i++){ const a=PR()*6.28, rr=PR()*st.rD*1.2; puffs.push({x:b.x+Math.cos(a)*rr,y:b.y+Math.sin(a)*rr,r:st.rD*(0.25+PR()*0.35)+0.4,t:b.t+PR()*0.3,dx:Math.cos(a)*(0.3+PR()*0.6),dy:Math.sin(a)*(0.3+PR()*0.6)-0.2,c:50+Math.floor(PR()*40)}); } });
      sim.anim=(g,T,world,screen,tx,showRed)=>{ const at=(performance.now()-t0)/1000; booms.forEach(b=>{ if(!b.snd&&at>=b.t){ b.snd=1; if(sim.onBoom) sim.onBoom(b.x,b.y,cfg.air==='gbu10'||cfg.air==='toma'?1.8:cfg.air==='gbu12'?1.3:0.8); } }); if(at>animEnd+5) return; world();
        const B=sim.B; if(cfg.air!=='mortar'&&at<impactAt){ /* designador láser (GBU) o ruta del misil */ if(cfg.air!=='toma'){ g.strokeStyle='rgba(255,40,40,'+(0.5+0.4*Math.sin(at*20))+')'; g.lineWidth=0.08; g.setLineDash([0.4,0.3]); g.beginPath(); g.moveTo(B.x,B.y); g.lineTo(st.aim[0],st.aim[1]); g.stroke(); g.setLineDash([]); g.fillStyle='#ff2a2a'; g.beginPath(); g.arc(st.aim[0],st.aim[1],0.35,0,7); g.fill();
            const k2=Math.max(0,Math.min(1,(at-impactAt*0.25)/(impactAt*0.75))); if(k2>0){ const wob=Math.sin(k2*18)*(1-k2)*2; const bx=st.at[0]+wob, by=st.at[1]-(1-k2)*0.0; g.fillStyle='rgba(0,0,0,0.35)'; g.beginPath(); g.arc(bx,by,0.4+(1-k2)*3.5,0,7); g.fill(); g.fillStyle='#d8d4c8'; g.save(); g.translate(bx,by); g.scale(1+k2*0.6,1+k2*0.6); g.beginPath(); g.ellipse(0,0,0.35,1.1,0,0,7); g.fill(); g.fillStyle='#7a2b22'; g.fillRect(-0.35,-1.2,0.7,0.25); g.restore(); } }
          else { const k2=Math.max(0,Math.min(1,(at-impactAt*0.2)/(impactAt*0.8))); const cs=[[-4,-4],[Mp.w+4,-4],[-4,Mp.h+4],[Mp.w+4,Mp.h+4]].sort((p,q)=>Math.hypot(q[0]-st.at[0],q[1]-st.at[1])-Math.hypot(p[0]-st.at[0],p[1]-st.at[1]))[0]; const sx=cs[0], sy=cs[1]; const x=sx+(st.at[0]-sx)*k2, y=sy+(st.at[1]-sy)*k2; for(let i=1;i<22;i++){ const kk=Math.max(0,k2-i*0.022); g.fillStyle='rgba(225,225,225,'+Math.max(0,0.4-i*0.017)+')'; g.beginPath(); g.arc(sx+(st.at[0]-sx)*kk,sy+(st.at[1]-sy)*kk,0.35+i*0.08,0,7); g.fill(); }
            const an=Math.atan2(st.at[1]-sy,st.at[0]-sx); g.save(); g.translate(x,y); g.rotate(an); g.scale(1.5,1.5); g.fillStyle='#e6e6e0'; g.fillRect(-1.4,-0.22,2.8,0.44); g.fillStyle='#ffb347'; g.beginPath(); g.arc(-1.5,0,0.25,0,7); g.fill(); g.fillStyle='#e6e6e0'; g.fillRect(-0.2,-0.9,0.35,1.8); g.restore(); } }
        booms.forEach(b=>{ const dt=at-b.t; if(cfg.air==='mortar'&&dt<0&&dt>-0.45){ g.strokeStyle='rgba(255,230,120,0.8)'; g.lineWidth=0.08; g.beginPath(); g.arc(b.x,b.y,0.3+(-dt)*6,0,7); g.stroke(); }
          if(dt>=0&&dt<1.4){ const k3=dt/1.4; g.globalAlpha=Math.max(0,1-k3); g.fillStyle='#ffcf6b'; g.beginPath(); g.arc(b.x,b.y,st.rD*(0.4+Math.min(1,dt*5)*0.9),0,7); g.fill(); g.fillStyle='#ff7a2a'; g.beginPath(); g.arc(b.x,b.y,st.rD*(0.3+Math.min(1,dt*4)*0.6),0,7); g.fill(); g.globalAlpha=Math.max(0,0.7-k3); g.strokeStyle='#fff0c0'; g.lineWidth=0.18; g.beginPath(); g.arc(b.x,b.y,Math.min(st.rL,Math.max(Mp.w,Mp.h)*1.2)*Math.min(1,dt*1.6),0,7); g.stroke(); g.globalAlpha=1; } });
        puffs.forEach(p=>{ const dt=at-p.t; if(dt<0.15||dt>4.5) return; const k3=dt/4.5; g.fillStyle='rgba('+p.c+','+(p.c-2)+','+(p.c-6)+','+(0.5*(1-k3))+')'; g.beginPath(); g.arc(p.x+p.dx*dt,p.y+p.dy*dt,p.r*(0.7+k3*1.2),0,7); g.fill(); });
        { const A_=st.aim; g.strokeStyle='rgba(255,255,255,0.9)'; g.lineWidth=0.09; g.setLineDash([0.3,0.2]); g.beginPath(); g.arc(A_[0],A_[1],0.9,0,7); g.stroke(); g.setLineDash([]); g.beginPath(); g.moveTo(A_[0]-1.4,A_[1]); g.lineTo(A_[0]+1.4,A_[1]); g.moveTo(A_[0],A_[1]-1.4); g.lineTo(A_[0],A_[1]+1.4); g.stroke(); /* punto de mira */
          booms.forEach(b=>{ if(at<b.t) return; g.strokeStyle='#ff3b30'; g.lineWidth=0.16; g.beginPath(); g.moveTo(b.x-0.6,b.y-0.6); g.lineTo(b.x+0.6,b.y+0.6); g.moveTo(b.x+0.6,b.y-0.6); g.lineTo(b.x-0.6,b.y+0.6); g.stroke(); }); } /* impactos */
        screen(); const fl=booms.map(b=>at-b.t).filter(d=>d>=0&&d<0.25); if(fl.length&&!rm){ g.fillStyle='rgba(255,245,220,'+(0.5*(1-fl[0]/0.25))+')'; g.fillRect(0,0,cv.width,cv.height); }
        if(at<animEnd){ g.font='700 13px system-ui,sans-serif'; g.textAlign='center'; const SHN={mortar:['Mortero de 120 mm','120 mm mortar'],gbu12:['GBU-12','GBU-12'],gbu10:['GBU-10','GBU-10'],toma:['Tomahawk','Tomahawk']}; const t=(at<impactAt?(st.icon+' '+LL(SHN[cfg.air]||st.n)+L(' en camino…',' inbound…')):LL(st.logN)); const w=g.measureText(t).width+20; const R_=cv.getBoundingClientRect(), W_=R_.width, H_=R_.height;
          /* el cartel no tapa las etiquetas de las unidades: arriba si no hay ninguna cerca del borde superior; si no, abajo (por encima de los botones) */ const vis=sim.agents.filter(a=>a.alive&&(!showRed||showRed(a))).map(a=>tx?tx(a.x,a.y):[0,-999]); const clash=y=>vis.some(([sx,sy])=>sy+24>y&&sy-30<y+24&&Math.abs(sx-W_/2)<w/2+16); const by=[8,H_-72,40,Math.round(H_/2-12)].find(y=>!clash(y)); if(by==null) return;
          g.fillStyle='rgba(10,14,18,0.7)'; g.fillRect(W_/2-w/2,by,w,24); g.fillStyle='#fff'; g.fillText(t,W_/2,by+17); } };
    }
    function strikeNote(){ if(!st||!sim.log) return; const m=nf(st.miss,1); const fp=st.rounds?[' de la primera granada',' of the first round']:['',''];
      sim.log('Punto de impacto'+fp[0]+': a '+m+' m del punto de mira ('+st.aimN+'); error circular probable '+nf(st.cep,1)+' m'+(st.cepEst?' (estimación)':''),'Impact point'+fp[1]+': '+m+' m from the aim point; circular error probable '+nf(st.cep,1)+' m'+(st.cepEst?' (estimate)':''),'air'); }
    const logEl=document.getElementById('cblog'); let nLog=0; const fmt=t=>Math.floor(t/60)+':'+String(Math.floor(t%60)).padStart(2,'0');
    function hud(){ const B=sim.B; document.getElementById('cbhpA').style.width=Math.max(0,B.hp)+'%'; document.getElementById('cbammo').textContent=(B.reloadT>0?L('Recargando…','Reloading…'):L('Cargador: ','Mag: ')+B.mag+'/'+B.kit.magSize)+(B.kit.frags?' · '+L('Granadas: ','Grenades: ')+B.frags:'')+(B.kit.plate?' · '+L('Placas ×','Plates ×')+B.kit.plateN:'');
      const alive=sim.reds.filter(a=>a.alive).length; document.getElementById('cbleft').textContent=alive+'/'+sim.reds.length; document.getElementById('cbdots').innerHTML=sim.reds.map(a=>'<i class="'+(a.alive?'':'x')+'"></i>').join(''); document.getElementById('cbtime').textContent=fmt(sim.T);
      for(let k=Math.max(0,nLog-4);k<nLog;k++){ const e=sim.ev[k]; if(e._li&&e._rev!==e.rev){ e._rev=e.rev; e._li.textContent=fmt(e.t1!=null?e.t1:e.t)+' · '+(EN()?e.en:e.es); } }
      while(nLog<sim.ev.length){ const e=sim.ev[nLog++]; const li=document.createElement('li'); li.className='c-'+(e.cls||''); li.textContent=fmt(e.t)+' · '+(EN()?e.en:e.es); e._li=li; e._rev=e.rev; logEl.insertBefore(li,logEl.firstChild); while(logEl.children.length>60) logEl.removeChild(logEl.lastChild); } }
    function frame(now){ if(dead) return; const dt=Math.min(0.1,(now-last)/1000); last=now; fts.push(dt); if(fts.length>40) fts.shift();
      if(!slowed&&fts.length===40){ const avg=fts.reduce((a,b)=>a+b,0)/40; if(avg>0.034){ slowed=1; vo.dprK=0.6; view.layout(); document.getElementById('cbslow').hidden=false; } }
      const at=(now-t0)/1000; if(st&&!applied&&at>=impactAt){ applied=true; sim.applyStrike(st); strikeNote(); sim.craters=(st.rounds||[st.at]).map(p=>[p[0],p[1],Math.max(1.2,st.rD)]); sim.mapVer=(sim.mapVer||0)+1; }
      if(!st||at>=animEnd){ const slow=slowA>=0&&sim.T>=slowA&&sim.T<slowEnd; const ban=document.getElementById('cbslowmo'); if(ban) ban.hidden=!slow; acc+=dt*(slow?0.2:speed); let n=0; while(acc>=1/30&&n<20&&!sim.over){ sim.step(1/30); acc-=1/30; n++; } }
      view.draw(); hud(); if(sim.over&&!shown){ if(!resT) resT=now; if(now-resT>1200){ shown=1; result(); } }
      raf=requestAnimationFrame(frame); }
    document.getElementById('cbsp').addEventListener('click',e=>{ speed=speed===1?2:speed===2?4:1; speedRef=speed; e.target.textContent='×'+speed; });
    document.getElementById('cbsnd').addEventListener('click',e=>{ SND_ON=!SND_ON; try{ localStorage.setItem('mat_combate_snd',SND_ON?'1':'0'); }catch(_){} e.currentTarget.textContent=SND_ON?'🔊':'🔇'; if(SND_ON) auInit(); });
    document.getElementById('cbskip').addEventListener('click',()=>{ sim.onShot=null; sim.onBoom=null; slowEnd=1e9; if(st&&!applied){ applied=true; sim.applyStrike(st); strikeNote(); sim.craters=(st.rounds||[st.at]).map(p=>[p[0],p[1],Math.max(1.2,st.rD)]); sim.mapVer=(sim.mapVer||0)+1; } animEnd=0; let n=0; while(!sim.over&&n++<9000) sim.step(1/30); resT=performance.now()-2000; });
    /* cámara lenta en el disparo final (2D): se simula la partida aparte con la misma semilla para saber cuándo cae el último disparo */
    let slowA=-1, slowEnd=-1; try{ const s2=C2.makeSim(cfg.map,KA,KR,simO); if(st) s2.applyStrike(st); let n2=0; while(!s2.over&&n2++<9000) s2.step(1/30); if(s2.over&&s2.lastKill&&s2.over.how==='ko'&&!s2.lastKill.gren&&Math.abs(s2.lastKill.T-s2.T)<0.2&&!rm){ slowA=s2.lastKill.T-0.7; slowEnd=s2.lastKill.T+0.5; } }catch(e){}
    const onR=()=>{ size(); view.layout(); }; window.addEventListener('resize',onR);
    ACTIVE={destroy(){ dead=true; cancelAnimationFrame(raf); window.removeEventListener('resize',onR); }};
    window.MAT_COMBATE_DBG={sim,view,setSpeed:v=>speed=v,cfg,st};
    raf=requestAnimationFrame(frame);
    function result(){ const B=sim.B, w=sim.over.w; const reasons=whyList(sim,cfg,st,KA,KR,PA,RS); const realism=100-(st?st.cost:0);
      const score=Math.max(0,Math.round((w===0?60+B.hp*0.3:sim.reds.filter(a=>!a.alive).length/sim.reds.length*40)+(st?0:10)-(st?st.cost:0)));
      const el=document.getElementById('cbres'); el.innerHTML='<div class="cb-card cb-res"><h2>'+(sim.over.how==='rescue'?L('🏆 Rehén rescatado','🏆 Hostage rescued'):sim.over.how==='hold'?L('🏆 Trinchera tomada','🏆 Trench taken'):sim.over.how==='hostage'?L('🔴 Misión fallida: el rehén ha muerto','🔴 Mission failed: the hostage is dead'):w===0?L('🏆 Gana tu soldado','🏆 Your soldier wins'):sim.over.how==='time'?L('⏱ Gana la IA: mantiene la posición','⏱ The AI wins: it holds the position'):L('🔴 Gana la IA','🔴 The AI wins'))+'</h2><p class="cb-note">'+LL(MAPN[cfg.map])+' · '+(cfg.night?L('noche','night'):L('día','day'))+' · '+(cfg.eq>1?cfg.eq+' '+L('contra','vs')+' ':'')+cfg.n+' × '+FAC[cfg.fac].flag+' · '+fmt(sim.T)+(st?' · '+st.icon+' '+esc(LL(st.n).replace(/ \(.*\)$/,'')):'')+' · '+LL(DIFN[cfg.dif])+' · '+LL(MISN[cfg.mi])+' · '+L('semilla ','seed ')+seed+'</p>'+
        '<h3 class="cb-h3">'+L('Por qué','Why')+'</h3><ol>'+reasons.map(r=>'<li>'+esc(r)+'</li>').join('')+'</ol><p><b>'+L('Puntuación: ','Score: ')+score+'/100</b> <span class="cb-est">'+L('Estimación','Estimate')+'</span><br><small>'+(w===0?L('60 por ganar + 30 × la salud que te queda','60 for winning + 30 × health left'):L('40 × la parte de enemigos abatidos','40 × the share of enemies taken down'))+(st?L(' − '+st.cost+' por el apoyo («realismo»)',' − '+st.cost+' for the strike (“realism”)'):L(' + 10 por entrar sin apoyo',' + 10 for going in without support'))+'</small></p>'+
        (()=>{ const k=sim.lastKill; if(!k||k.gren||sim.over.how!=='ko') return ''; return '<div class="cb-rp"><h3 class="cb-h3">'+L('🎬 Repetición 3D del disparo final','🎬 3D replay of the final shot')+'</h3><div class="cb-rpst" id="cbrp" hidden></div><button type="button" class="cb-btn sec" id="cbrpb">'+L('▶ Ver la repetición 3D','▶ Watch the 3D replay')+'</button> <span class="cb-note">'+L('Con los soldados 3D de «Crea tu soldado», en un escenario de campo abierto.','With the 3D soldiers from “Build your soldier”, on an open-field set.')+'</span></div>'; })()+'<div class="cb-chips"><button type="button" class="cb-btn" id="cbrev">'+L('🔁 Revancha','🔁 Rematch')+'</button><button type="button" class="cb-btn sec" id="cbrep">'+L('Repetir (misma semilla)','Replay (same seed)')+'</button><button type="button" class="cb-btn sec" id="cbmapb">'+L('Cambiar mapa','Change map')+'</button><a class="cb-btn sec" href="#/soldado">'+L('Cambiar equipo','Change kit')+'</a><button type="button" class="cb-btn sec" id="cbshare">'+L('🔗 Compartir esta partida','🔗 Share this game')+'</button></div><p class="cb-note" id="cbsharemsg" hidden></p></div>';
      const rpb=document.getElementById('cbrpb'); if(rpb) rpb.onclick=()=>replay(sim,PA,RS,KA);
      document.getElementById('cbshare').onclick=async()=>{ const u=location.origin+location.pathname+'#/soldado/combate?f='+cfg.fac+'&m='+cfg.map+'&n='+cfg.n+'&t='+(cfg.night?'noche':'dia')+'&a='+cfg.air+'&d='+cfg.dif+'&mi='+cfg.mi+'&e='+cfg.eq+'&s='+seed; const msg=document.getElementById('cbsharemsg'); const tx_=L('Mi combate en M.A.T: ','My fight on M.A.T: ')+(w===0?L('gané','I won'):L('perdí','I lost'))+'. '+L('¿Lo haces mejor con la misma partida?','Can you do better in the same game?');
        try{ if(navigator.share){ await navigator.share({title:'M.A.T · Combate',text:tx_,url:u}); return; } }catch(e){ if(e&&e.name==='AbortError') return; }
        let ok=false; try{ await navigator.clipboard.writeText(u); ok=true; }catch(e){} msg.hidden=false; msg.innerHTML=(ok?L('Enlace copiado. Quien lo abra juega la misma partida (misma semilla, mapa, misión, dificultad y apoyo):','Link copied. Whoever opens it plays the same game (same seed, map, mission, difficulty and support):'):L('Copia este enlace: abre la misma partida (misma semilla, mapa, misión, dificultad y apoyo):','Copy this link: it opens the same game (same seed, map, mission, difficulty and support):'))+'<br><input type="text" readonly value="'+esc(u)+'" style="width:100%;font-size:12px;margin-top:4px" onclick="this.select()">'; };
      document.getElementById('cbrev').onclick=()=>fight(PA,RS,1+Math.floor(Math.random()*99999)); document.getElementById('cbrep').onclick=()=>fight(PA,RS,seed);
      document.getElementById('cbmapb').onclick=()=>{ const m=document.getElementById('cbmap'); if(m) try{ m.scrollIntoView({behavior:RM()?'auto':'smooth',block:'center'}); }catch(e){} };
      try{ el.scrollIntoView({behavior:RM()?'auto':'smooth',block:'nearest'}); }catch(e){} } }
  async function replay(sim,PA,RS,KA){ stopReplay(); const k=sim.lastKill; const box=document.getElementById('cbrp'), btn=document.getElementById('cbrpb'); if(!box||!k) return; box.hidden=false; btn.disabled=true; btn.textContent=L('Cargando el 3D…','Loading 3D…');
    const killer=sim.agents.find(a=>a.id===k.a), victim=sim.agents.find(a=>a.id===k.t); if(!killer||!victim){ btn.hidden=true; return; }
    const redA=killer.team===1?killer:victim; const ri=redA.id-1; const mg=cfg.n>=4&&ri===cfg.n-1; const stB=aiSt(cfg.fac,mg); const stA=loadSt(); if(!stA.arma&&stA.role){ const r=DATA.roles.find(x=>x.id===stA.role); if(r) stA.arma=r.arma; }
    const rm=RM(); let G=null;
    try{ const C3=await import('./combate3d.js?v='+VER); const low=Math.min(window.innerWidth,window.innerHeight)<500||(navigator.hardwareConcurrency||8)<=4;
      G=await C3.create(box,{M:ARM,A:{st:stA,D:DATA,tracer:0xffd36b},B:{st:stB,D:DATA,tracer:FAC[cfg.fac].tracer},red:rm,low,seed:seed}); }
    catch(e){ console.warn('replay 3d',e); box.innerHTML='<p class="cb-note" style="padding:12px">'+L('El 3D no se pudo cargar en este dispositivo.','3D could not load on this device.')+'</p>'; btn.hidden=true; return; }
    if(!document.getElementById('cbrp')){ G.destroy(); return; } REPLAY=G; btn.hidden=true;
    const cap=document.createElement('div'); cap.className='cb-rpcap'; box.appendChild(cap); const ld=document.createElement('div'); ld.className='cb-rpload'; ld.textContent=L('Cargando los soldados y sus armas…','Loading the soldiers and their weapons…'); box.appendChild(ld);
    const SH=killer.team===0?G.A:G.B, TG=killer.team===0?G.B:G.A; const dd=Math.max(5,Math.min(13,k.d));
    G.A.grp.position.set(-dd/2,0,-3.2); G.B.grp.position.set(dd/2,0,-3.2); [G.A,G.B].forEach(S=>{ S.at=-1; S.grp.updateMatrixWorld(true); }); G.face(G.A,true); G.face(G.B,true);
    const wait=ms=>new Promise(r=>setTimeout(r,ms/(window.MAT_CB_TS||1))); const live=()=>REPLAY===G&&!!document.getElementById('cbrp');
    async function run(){ await G.ready(); if(!live()) return; await Promise.all([G.setPose(SH,'apunta'),G.setPose(TG,'apunta')]); G.face(SH,true); G.face(TG,true); if(!live()) return; ld.remove(); cap.textContent=(killer===sim.B?L('Tu soldado','Your soldier'):killer.name)+' · '+killer.kit.short+' · '+L('a ','at ')+nf(k.d)+' m'+(Math.abs(dd-k.d)>0.6?L(' (en la escena, '+nf(dd)+' m)',' (on set, '+nf(dd)+' m)'):'');
      G.camera('two',SH,true); await Promise.all([G.setPose(SH,'apunta'),G.setPose(TG,'apunta')]); G.face(SH,true); G.face(TG,true); if(!live()) return;
      await wait(rm?200:1400); G.camera('behind',SH,true); await wait(rm?300:1100); if(!live()) return;
      const n=killer.kit.mg?4:killer.kit.auto?3:1; const list=[]; for(let i=0;i<n-1;i++) list.push({hit:false}); list.push({hit:true,loc:k.loc==='head'?'head':k.loc==='limb'?'limb':'torso',stop:false});
      const iv=60/(killer.kit.rate||700); const ms=G.shots(SH,list,iv); await wait(ms*0.75); if(!live()) return; G.camera('victim',TG,true); G.shake(0.05); await G.fall(TG,{side:seed%2?1:-1}); if(!live()) return;
      cap.textContent=(victim===sim.B?L('Tu soldado, fuera de combate','Your soldier, out of action'):victim.name+L(', fuera de combate',', out of action'))+(k.loc==='head'?L(' (impacto en la cabeza)',' (head hit)'):'');
      G.camera('orbit',TG); await wait(rm?800:3200); if(!live()) return; const again=document.createElement('button'); again.type='button'; again.className='cb-btn sec cb-rpag'; again.textContent=L('↻ Repetir','↻ Replay'); again.onclick=()=>replay(sim,PA,RS,KA); box.appendChild(again); }
    run(); try{ box.scrollIntoView({behavior:rm?'auto':'smooth',block:'center'}); }catch(e){} }
  render(); }
function whyList(sim,cfg,st,KA,KR,PA,RS){ const B=sim.B, w=sim.over.w, out=[]; const reds=sim.reds; const N=reds.length; const kb=KR[0]; const nm=cfg.fac==='ru'?L('rusos','Russian'):L('estadounidenses','US');
  const hw=sim.over.how; if(hw==='rescue') out.push([10,L('Tu soldado llegó hasta el rehén a los '+Math.round(sim.T)+' s','Your soldier reached the hostage after '+Math.round(sim.T)+' s')]); if(hw==='hold') out.push([10,L('Tu soldado mantuvo el tramo central 6 s sin enemigos dentro','Your soldier held the central bay for 6 s with no enemy inside')]); if(hw==='hostage') out.push([10,L('El rehén murió alcanzado por una explosión: con rehenes, el apoyo y las granadas son un riesgo','The hostage was killed by an explosion: with hostages, strikes and grenades are a risk')]);
  { const al=sim.allies||[]; if(al.length){ const down=al.filter(a=>!a.alive).length, ak=al.reduce((s_,a)=>s_+a.kills,0); out.push([6+ak,L('Tu '+(al.length>1?'grupo':'binomio')+': '+(ak?'tus compañeros abatieron a '+ak:'tus compañeros no abatieron a nadie')+(down?' y cayeron '+down:' y todos siguieron en pie'),'Your '+(al.length>1?'team':'pair')+': '+(ak?'your teammates took down '+ak:'your teammates took nobody down')+(down?' and '+down+' went down':' and all stayed on their feet'))]); }
    const bq=sim.blueSquad; if(bq&&bq.seq.length) out.push([4,L('Tu equipo despejó '+bq.seq.length+(bq.seq.length>1?' habitaciones':' habitación')+' una a una: '+bq.seq.map(ri=>LL(sim.M.rooms[ri][4])).join(', '),'Your team cleared '+bq.seq.length+' room'+(bq.seq.length>1?'s':'')+' one by one: '+bq.seq.map(ri=>LL(sim.M.rooms[ri][4])).join(', '))]);
    const rq=(sim.squads||[]).filter(q=>q.team===1); const rs=rq.reduce((s_,q)=>s_+q.seq.length,0); if(rs) out.push([3,L('El equipo enemigo despejó '+rs+(rs>1?' habitaciones':' habitación')+' buscándote','The enemy team cleared '+rs+' room'+(rs>1?'s':'')+' looking for you')]); }
  if(cfg.dif==='rec') out.push([6,L('IA en «Recluta»: apunta más despacio y acierta la mitad','AI on “Recruit”: slower to aim, half the hits')]); if(cfg.dif==='eli') out.push([6,L('IA en «Élite»: apunta más rápido y acierta un 75 % más','AI on “Elite”: faster to aim, 75 % more hits')]);
  if(st&&st.killed) out.push([9,L(LL(st.logN).replace(/^Impacto (de la|del) /,'La ').replace(/^La Tomahawk/,'El Tomahawk')+' eliminó a '+st.killed+' de '+N+' antes de entrar'+(st.walls?' y destruyó '+st.walls+' tramos de muro':''),LL(st.logN).replace(/ impact$/,'')+' took out '+st.killed+' of '+N+' before you went in'+(st.walls?' and destroyed '+st.walls+' wall sections':''))]);
  if(st&&!st.killed) out.push([5,L('El apoyo no eliminó a nadie: los muros y la trinchera protegieron a los defensores','The strike killed nobody: walls and trenches shielded the defenders')]);
  if(B.stops) out.push([B.stops*3,L('Tu placa paró '+B.stops+' impacto'+(B.stops>1?'s':''),'Your plate stopped '+B.stops+' hit'+(B.stops>1?'s':''))]);
  const rs=reds.reduce((s,a)=>s+a.stops,0); if(rs) out.push([rs*2,L('Las placas de los '+nm+' pararon '+rs+' de tus impactos','The '+nm+' plates stopped '+rs+' of your hits')]);
  if(!KA.plate&&B.hitsT) out.push([4,L('No llevabas placas para fusil: cada impacto en el torso hizo daño completo','You had no rifle plates: every torso hit did full damage')]);
  if(cfg.night){ if(KA.nvg&&!kb.nvg) out.push([6+B.nightKills*2,L('Las NVG te dieron ventaja de noche: veías unos 40 m en todo el cono; ellos '+(kb.nightSight?'solo por el visor de su arma (cono estrecho)':'unos 8 m')+(B.nightKills?' — abatiste a '+B.nightKills+' sin que te vieran':''),'Night vision gave you the edge: about 40 m across your whole cone; they saw '+(kb.nightSight?'only through their weapon sight (narrow cone)':'about 8 m')+(B.nightKills?' — you took down '+B.nightKills+' unseen':''))]);
    if(!KA.nvg) out.push([6,L('Sin visor nocturno '+(KA.light?'tu linterna alumbraba 25 m pero te delataba':'solo veías unos 8 m'),'Without night vision '+(KA.light?'your light reached 25 m but gave you away':'you saw only about 8 m'))]);
    if(KA.nvg&&KA.irLaser) out.push([3,L('Con el láser IR y las NVG apuntabas casi como de día','With the IR laser and night vision you aimed almost as by day')]); }
  if(w===1&&B.headK) out.push([8,L('Un impacto en la cabeza decidió el combate: '+(PA.helmet?'el casco protege de metralla y pistola, no de balas de fusil':'no llevabas casco'),'A single head hit decided it: '+(PA.helmet?'the helmet stops fragments and pistol rounds, not rifle rounds':'you had no helmet'))]);
  const hk=reds.filter(a=>a.headK).length; if(hk) out.push([3+hk,L(hk+' enemigo'+(hk>1?'s cayeron':' cayó')+' por un impacto en la cabeza',hk+' enem'+(hk>1?'ies went':'y went')+' down to a head hit')]);
  const gk=B.gKills||0; if(gk) out.push([5+gk,L('Tu granada M67 dejó fuera de combate a '+gk,'Your M67 grenade took out '+gk)]);
  const killer=sim.agents.find(a=>a.id===B.killedBy); if(w===1&&killer&&(killer.flankRun||killer.flankDone)) out.push([7,L('Te flanquearon: '+killer.name+' cambió de posición y te sorprendió','You were flanked: '+killer.name+' moved and caught you')]);
  if(w===1&&killer&&killer.kit.mg) out.push([5,L('La ametralladora enemiga te fijó con fuego de supresión','The enemy machine gun pinned you down with suppressive fire')]);
  { const nb=1+(sim.allies||[]).length; if(N>=3&&nb<N) out.push([N-nb+1,L((nb===1?'Uno':nb===2?'Dos':nb)+' contra '+N+': cada esquina podía esconder a alguien',(nb===1?'One':nb===2?'Two':nb)+' against '+N+': every corner could hide someone')]); }
  const accA=B.fired?B.hits/B.fired:0, fr=reds.reduce((s,a)=>s+a.fired,0), hr=reds.reduce((s,a)=>s+a.hits,0); if(B.fired||fr) out.push([2,L('Puntería: tú '+Math.round(accA*100)+' % ('+B.hits+'/'+B.fired+'); la IA '+(fr?Math.round(hr/fr*100):0)+' % ('+hr+'/'+fr+')','Accuracy: you '+Math.round(accA*100)+' % ('+B.hits+'/'+B.fired+'); the AI '+(fr?Math.round(hr/fr*100):0)+' % ('+hr+'/'+fr+')')]);
  if(KA.move>1.2) out.push([2,L('Tu carga ('+nf(PA.pct)+' % de tu peso) te hacía más lento al moverte entre coberturas','Your load ('+nf(PA.pct)+' % of body weight) slowed you between cover')]);
  if(sim.lastKill&&sim.lastKill.T>sim.T-2&&!sim.lastKill.gren) out.push([1,L('Último disparo a '+Math.round(sim.lastKill.d)+' m','Final shot at '+Math.round(sim.lastKill.d)+' m')]);
  if(sim.over.how==='strike') return [out.find(r=>r[0]===9)[1],L('Tu soldado no tuvo que entrar: la misión se resolvió desde el aire, con un coste de −'+st.cost+' puntos de realismo','Your soldier never had to go in: the mission was settled from the air, at a cost of −'+st.cost+' realism points')];
  if(sim.over.how==='time') out.unshift([99,L('Se acabaron los 4 minutos de la misión sin limpiar la posición','The 4-minute mission ran out before the position was cleared')]);
  return out.sort((a,b)=>b[0]-a[0]).slice(0,6).map(r=>r[1]); }
